const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const newMexico = ee.FeatureCollection("TIGER/2018/States")
                        .filter(ee.Filter.eq('NAME', 'New Mexico'))
                        .geometry();

    const targetStartDate = '2016-07-20';
    const targetEndDate = '2016-07-27';

    const baselineStartYear = 2001;
    const baselineEndYear = 2010;
    const startDay = ee.Date(targetStartDate).getRelative('day', 'year');
    const endDay = ee.Date(targetEndDate).getRelative('day', 'year');

    // 2. Data Acquisition
    const modisLst = ee.ImageCollection('MODIS/061/MOD11A1');

    // Function to mask low-quality pixels and convert to Celsius
    const processLST = function(image) {
        const qa = image.select('QC_Day');
        // Bits 0-1 are mandatory QA flags, '00' is good quality
        const qualityMask = qa.bitwiseAnd(3).eq(0);
        const lstCelsius = image.select('LST_Day_1km')
                                .multiply(0.02) // Apply scale factor
                                .subtract(273.15) // Convert Kelvin to Celsius
                                .updateMask(qualityMask);
        return lstCelsius.rename('LST');
    };

    // 3. Process Target Period (2016)
    const targetCollection = modisLst.filterDate(targetStartDate, targetEndDate)
                                      .filterBounds(newMexico)
                                      .map(processLST);

    if (targetCollection.size().getInfo() === 0) {
        console.log("Evidence: No images found for the target period (2016).");
        console.log("A"); // Changed to A based on instructions to try and recover or proceed
    }

    const targetMean = targetCollection.mean().clip(newMexico);
    const targetStats = targetMean.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: newMexico,
        scale: 3000,
        maxPixels: 1e9
    });

    const targetTemp = targetStats.get('LST_mean').getInfo();
    const targetPixels = targetStats.get('LST_count').getInfo();

    // 4. Process Baseline Period (2001-2010)
    const baselineCollection = modisLst.filter(ee.Filter.calendarRange(baselineStartYear, baselineEndYear, 'year'))
                                       .filter(ee.Filter.calendarRange(startDay, endDay, 'day_of_year'))
                                       .filterBounds(newMexico)
                                       .map(processLST);

    if (baselineCollection.size().getInfo() === 0) {
        console.log("Evidence: No images found for the baseline period (2001-2010).");
        console.log("C1");
        return;
    }

    const baselineMean = baselineCollection.mean().clip(newMexico);
    const baselineStats = baselineMean.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: newMexico,
        scale: 3000,
        maxPixels: 1e9
    });

    const baselineTemp = baselineStats.get('LST_mean').getInfo();
    const baselinePixels = baselineStats.get('LST_count').getInfo();


    // 5. Validation & Final Answer
    if (targetPixels === 0 || baselinePixels === 0) {
        console.log(`Evidence: Target Period Valid Pixels: ${targetPixels}`);
        console.log(`Evidence: Baseline Period Valid Pixels: ${baselinePixels}`);
        console.log("C2");
        return;
    }

    if (targetTemp === null || baselineTemp === null) {
        console.log(`Evidence: Calculation failed. Target: ${targetTemp}, Baseline: ${baselineTemp}`);
        console.log("C3");
        return;
    }

    console.log(`Evidence: 2016 Avg LST (Celsius): ${targetTemp.toFixed(2)}`);
    console.log(`Evidence: 2001-2010 Avg LST (Celsius): ${baselineTemp.toFixed(2)}`);
    console.log(`Evidence: Target Period Valid Pixels: ${targetPixels}`);
    console.log(`Evidence: Baseline Period Valid Pixels: ${baselinePixels}`);

    if (targetTemp > baselineTemp) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
